// Family Feud: name the survey's top answers. Questions and answers come from the topic's trivia surveys.
import type { Survey } from "../trivia/types";
import { next, shuffle } from "../rng";

export const BOARD_POINTS = [50, 30, 20, 15, 10];
export const MAX_STRIKES = 3;

export type FeudRound = {
  q: string;
  board: string[]; // top answers, best first
  options: string[]; // shuffled choices: the board plus wrong answers
  found: Record<string, string>; // answer -> player who named it
  wrong: string[];
  strikes: number;
};

export type FeudState = {
  players: string[];
  rounds: FeudRound[];
  round: number;
  turn: number; // guesses made this round
  points: Record<string, number>;
  done: boolean;
  seed: number;
};

export function init(o: { players: string[]; surveys: Survey[]; rounds: number; seed: number }): FeudState {
  let seed = o.seed;
  const [picked, s1] = shuffle(o.surveys, seed);
  seed = s1;
  const rounds: FeudRound[] = picked.slice(0, o.rounds).map((sv) => {
    const [options, sn] = shuffle([...sv.answers.slice(0, BOARD_POINTS.length), ...sv.decoys], seed);
    seed = sn;
    return { q: sv.q, board: sv.answers.slice(0, BOARD_POINTS.length), options, found: {}, wrong: [], strikes: 0 };
  });
  return { players: o.players, rounds, round: 0, turn: 0, points: Object.fromEntries(o.players.map((p) => [p, 0])), done: rounds.length === 0, seed };
}

export const turnPlayer = (s: FeudState) => (s.done ? null : s.players[(s.round + s.turn) % s.players.length]!);
export const roundDone = (r: FeudRound) => r.strikes >= MAX_STRIKES || Object.keys(r.found).length >= r.board.length;

export function choose(s: FeudState, by: string, answer: string): FeudState {
  if (s.done || turnPlayer(s) !== by) return s;
  const r = s.rounds[s.round]!;
  if (!r.options.includes(answer) || r.found[answer] || r.wrong.includes(answer)) return s;
  const rank = r.board.indexOf(answer);
  const nr: FeudRound = rank >= 0 ? { ...r, found: { ...r.found, [answer]: by } } : { ...r, wrong: [...r.wrong, answer], strikes: r.strikes + 1 };
  const points = rank >= 0 ? { ...s.points, [by]: s.points[by]! + BOARD_POINTS[rank]! } : s.points;
  const rounds = s.rounds.map((x, i) => (i === s.round ? nr : x));
  if (roundDone(nr)) {
    const round = s.round + 1;
    return { ...s, rounds, points, round, turn: 0, done: round >= s.rounds.length };
  }
  return { ...s, rounds, points, turn: s.turn + 1 };
}

/** AI: usually names the best answer left, sometimes a wrong one. */
export function aiChoose(s: FeudState): { choice: string; seed: number } {
  const r = s.rounds[s.round]!;
  const [x, seed] = next(s.seed);
  const open = r.options.filter((a) => !r.found[a] && !r.wrong.includes(a));
  const good = r.board.filter((a) => !r.found[a]);
  const bad = open.filter((a) => !r.board.includes(a));
  const choice = (x < 0.68 && good.length ? good[0]! : bad.length ? bad[Math.floor((x * 997) % bad.length)]! : open[0]!) ?? open[0]!;
  return { choice, seed };
}
